/**
 * ProfileSyncBlob
 *
 * The shape is intentionally `Any` — the frontend owns the schema.
 *
 * This is a pastebin slot; we don't validate sub-fields because the
 * feature set evolves on the client and the backend shouldn't be a
 * moving target every time we add a new tab.
 */
export type ProfileSyncBlob = {
    /**
     * Blob
     *
     * Arbitrary client-managed payload.
     */
    blob: unknown;
};

/**
 * RangeFilter
 *
 * Inclusive numeric range used by `SearchFilters.distance` /
 * `.population`. Either bound is optional — omit `min` for an upper-
 * only filter, omit `max` for a lower-only one. (Frontend always
 * sends both today; keep them optional so a future client can omit.)
 */
export type RangeFilter = {
    /**
     * Min
     */
    min?: number | null;
    /**
     * Max
     */
    max?: number | null;
    [key: string]: unknown;
};

/**
 * RankingIdentity
 *
 * Echoes the versioned V3 ranking profile + pinned derived generation
 * that produced a ranked response (F2c/F3 Task 5), so a client or an
 * operator can tell exactly which profile+generation combination is
 * behind a given result set without spelunking through logs.
 *
 * `ranking_sha256` is `edfinder_api.ranking.profile.ranking_sha256()` at
 * response time -- it must always equal the live profile's hash, never a
 * value baked in ahead of time.
 */
export type RankingIdentity = {
    /**
     * Ranking Version
     */
    ranking_version: string;
    /**
     * Ranking Sha256
     */
    ranking_sha256: string;
    /**
     * Derived Generation Id
     */
    derived_generation_id: string;
    /**
     * Publication Sequence
     */
    publication_sequence: number;
    /**
     * Archetype Version
     */
    archetype_version: string;
    /**
     * Archetype Manifest Sha256
     */
    archetype_manifest_sha256: string;
    /**
     * Archetype Model Sha256
     */
    archetype_model_sha256: string;
};

